    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Find the full straight marker line, colored differently from the background.
    marker = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            marker = ("row", r, grid[r][0])
            break
