                marker = ("col", c, grid[0][c])
                break
    if marker is None:
        return [row[:] for row in grid]

    orient, pos, marker_color = marker
    obj_colors = [color for color in counts if color not in (bg, marker_color)]
    if not obj_colors:
        return [row[:] for row in grid]
    obj = max(obj_colors, key=lambda color: counts[color])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    if not cells:
        return [row[:] for row in grid]

